#pragma once
#include <JuceHeader.h>
#include <cmath>

namespace vdsp
{

inline float dbToGain (float db) noexcept { return std::pow (10.0f, db * 0.05f); }
inline float gainToDb (float g)  noexcept { return 20.0f * std::log10 (juce::jmax (g, 1.0e-9f)); }

//==============================================================================
class CompressorLite
{
public:
    void prepare (double sr) { sampleRate = sr; reset(); }
        void reset() { envDb = 0.0f; grDb = 0.0f; }

            void setParams (float thresholdDb, float ratio_, float attackMs, float releaseMs)
                {
                        thrDb = thresholdDb;
                                ratio = juce::jmax (1.0f, ratio_);
                                        atkC  = timeCoef (attackMs);
                                                relC  = timeCoef (releaseMs);
                                                    }

                                                        float processSample (float detector) noexcept
                                                            {
                                                                    const float inDb   = gainToDb (detector);
                                                                            const float over   = inDb - thrDb;
                                                                                    const float target = (over > 0.0f) ? -over * (1.0f - 1.0f / ratio) : 0.0f;

                                                                                            if (target < envDb) envDb = target + atkC * (envDb - target);
                                                                                                    else                envDb = target + relC * (envDb - target);

                                                                                                            grDb = envDb;
                                                                                                                    return dbToGain (envDb);
                                                                                                                        }

                                                                                                                            float getGainReductionDb() const noexcept { return grDb; }

                                                                                                                            private:
                                                                                                                                float timeCoef (float ms) const noexcept
                                                                                                                                    {
                                                                                                                                            if (ms <= 0.0f) return 0.0f;
                                                                                                                                                    return std::exp (-1.0f / (float (sampleRate) * ms * 0.001f));
                                                                                                                                                        }

                                                                                                                                                            double sampleRate = 44100.0;
                                                                                                                                                                float thrDb = -18.0f, ratio = 2.0f, atkC = 0.0f, relC = 0.0f, envDb = 0.0f, grDb = 0.0f;
                                                                                                                                                                };

                                                                                                                                                                //==============================================================================
                                                                                                                                                                class GateLite
                                                                                                                                                                {
                                                                                                                                                                public:
                                                                                                                                                                    void prepare (double sr) { sampleRate = sr; reset(); }
                                                                                                                                                                        void reset() { envDb = 0.0f; }

                                                                                                                                                                            void setParams (float thresholdDb, float rangeDb_, float attackMs, float releaseMs)
                                                                                                                                                                                {
                                                                                                                                                                                        thrDb = thresholdDb;
                                                                                                                                                                                                rangeDb = juce::jmax (0.0f, rangeDb_);
                                                                                                                                                                                                        atkC = timeCoef (attackMs);
                                                                                                                                                                                                                relC = timeCoef (releaseMs);
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                        float processSample (float detector) noexcept
                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                    const float inDb   = gainToDb (detector);
                                                                                                                                                                                                                                            const float target = (inDb > thrDb) ? 0.0f : -rangeDb;

                                                                                                                                                                                                                                                    if (target > envDb) envDb = target + atkC * (envDb - target);
                                                                                                                                                                                                                                                            else                envDb = target + relC * (envDb - target);

                                                                                                                                                                                                                                                                    return dbToGain (envDb);
                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                        private:
                                                                                                                                                                                                                                                                            float timeCoef (float ms) const noexcept
                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                        if (ms <= 0.0f) return 0.0f;
                                                                                                                                                                                                                                                                                                return std::exp (-1.0f / (float (sampleRate) * ms * 0.001f));
                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                        double sampleRate = 44100.0;
                                                                                                                                                                                                                                                                                                            float thrDb = -45.0f, rangeDb = 20.0f, atkC = 0.0f, relC = 0.0f, envDb = 0.0f;
                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                            //==============================================================================
                                                                                                                                                                                                                                                                                                            struct SaturatorLite
                                                                                                                                                                                                                                                                                                            {
                                                                                                                                                                                                                                                                                                                enum Type { Tube = 0, Tape, Diode };

                                                                                                                                                                                                                                                                                                                    static float shape (float x, int type) noexcept
                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                switch (type)
                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                    case Tube:  return std::tanh (x);
                                                                                                                                                                                                                                                                                                                                                                case Tape:  { const float a = juce::jlimit (-1.5f, 1.5f, x); return a - (a * a * a) / 3.0f; }
                                                                                                                                                                                                                                                                                                                                                                            case Diode:
                                                                                                                                                                                                                                                                                                                                                                                        default:    return x / (1.0f + std::abs (x));
                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                    //==============================================================================
                                                                                                                                                                                                                                                                                                                                                                                                    class LimiterLite
                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                    public:
                                                                                                                                                                                                                                                                                                                                                                                                        void prepare (double sr) { sampleRate = sr; reset(); }
                                                                                                                                                                                                                                                                                                                                                                                                            void reset() { env = 1.0f; }

                                                                                                                                                                                                                                                                                                                                                                                                                void setParams (float ceilingDb, float releaseMs)
                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                            ceiling = dbToGain (ceilingDb);
                                                                                                                                                                                                                                                                                                                                                                                                                                    relC = std::exp (-1.0f / (float (sampleRate) * releaseMs * 0.001f));
                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                            void process (juce::AudioBuffer<float>& buffer) noexcept
                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const int numCh = buffer.getNumChannels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                const int n = buffer.getNumSamples();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int i = 0; i < n; ++i)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            float peak = 0.0f;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int c = 0; c < numCh; ++c)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        peak = juce::jmax (peak, std::abs (buffer.getSample (c, i)));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const float g = (peak > ceiling) ? ceiling / peak : 1.0f;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (g < env) env = g;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            else         env = g + relC * (env - g);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (int c = 0; c < numCh; ++c)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    float s = buffer.getSample (c, i) * env;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    buffer.setSample (c, i, juce::jlimit (-ceiling, ceiling, s));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            private:
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                double sampleRate = 44100.0;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    float ceiling = 1.0f, relC = 0.0f, env = 1.0f;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } // namespace vdsp